{
  "name": "@amykit/plugin-hermes-agent",
  "version": "0.9.1",
  "description": "Hermes as the agent, over its one-shot mode and usage report.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/hermes-agent"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Use it when the agent should be Hermes, run in one-shot mode under a profile of its own so amy never touches your personal Hermes setup. It contributes a harness and a usage reader to agent-relay, so install the relay beside it. amy add prepares the profile and amy doctor checks it. A skill a step names is passed with -s, and the profile's skills.external_dirs names amy's skill root so the name resolves."
  },
  "dependencies": {
    "@amykit/core": "^0.9.1",
    "@amykit/agent-kit": "^0.9.1",
    "@amykit/model-specs": "^0.9.1"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AgentOutcome, AgentRun, AskContext, CommandResult, CommandRunner, Harness, HarnessReply, TokenUsage } from "@amykit/core";
import { costOf, specFor } from "@amykit/model-specs";
import { externalDirsIn } from "./profile.js";

export interface HermesHarnessConfig {
  model?: string;
  timeoutMs?: number;
  /**
   * The profile the run is in. Without one, `-z` runs in the operator's own
   * Hermes: their memory read into the run, and whatever it learns written
   * back, with approvals bypassed.
   */
  profile?: string;
}

/** The report `--usage-file` writes, which it writes even on a failed run. */
export interface HermesUsage {
  estimated_cost_usd?: number;
  cost_status?: string;
  cost_source?: string;
  input_tokens?: number;
  output_tokens?: number;
  cache_read_tokens?: number;
  cache_write_tokens?: number;
  model?: string;
  provider?: string;
  completed?: boolean;
  failed?: boolean;
  failure_reason?: string;
  failure_resets_at?: string;
}

/**
 * Where a Hermes profile keeps its skills.
 *
 * A named profile has its own `skills` directory, cloned from the active one,
 * so that is the set the run reads. Without a profile the operator's own
 * `~/.hermes/skills` is the one, which is exactly the setup `-p` exists to
 * avoid.
 */
export function skillsRoot(profile: string | undefined, hermesHome = process.env.HERMES_HOME ?? path.join(os.homedir(), ".hermes")): string {
  return profile ? path.join(hermesHome, "profiles", profile, "skills") : path.join(hermesHome, "skills");
}

/**
 * Hermes, over its one-shot mode.
 *
 * `-z` prints only the final response, and `--usage-file` writes the account
 * beside it. The account is written **even when the run fails**, which is the
 * nicest property of the three harnesses: a failed run still says what it
 * spent, so nothing is silently free.
 */
export class HermesHarness implements Harness {
  readonly name = "hermes";
  /** It is handed a skill by name: `-s`, resolved through the profile. */
  readonly lendsSkill = true;
  /** The skills the profile amy runs in reads. */
  readonly skillsDirectory: string;
  private readonly hermesHome: string;

  constructor(
    private readonly runner: CommandRunner,
    private readonly config: HermesHarnessConfig = {},
    private readonly tmpDir: string = os.tmpdir(),
  ) {
    this.hermesHome = process.env.HERMES_HOME ?? path.join(os.homedir(), ".hermes");
    this.skillsDirectory = skillsRoot(config.profile, this.hermesHome);
  }

  async ask(prompt: string, cwd: string, context: AskContext = {}): Promise<HarnessReply> {
    // `-z` has no mode that keeps the agent's tools off the checkout, so a run
    // that must change nothing is refused before it starts, and a relay hands
    // it to a harness that can enforce it.
    if (context.readOnly) {
      return this.refused("hermes -z cannot run without write access to the checkout, so it does not take a read-only step");
    }
    const profileArgs = this.config.profile ? ["-p", this.config.profile] : [];
    // `-s` resolves the name through the profile's roots. If a local copy in a
    // higher tier would answer instead, or the lent directory is in no root the
    // profile reads, the turn is refused before it runs: `-s` would load the
    // wrong skill, or none, and the run would look like work.
    const refuses = context.skill ? await this.refusal(context.skill, profileArgs) : undefined;
    if (refuses) return this.refused(refuses);
    const report = path.join(this.tmpDir, `amy-hermes-${process.pid}-${Date.now()}.json`);
    const args = [...profileArgs];
    // The skill the prompt is addressed to, by name: the profile's
    // `external_dirs` is where Hermes finds amy's root, and `-s` is which
    // skill in it this turn must load.
    if (context.skill) args.push("-s", context.skill.name);
    args.push("-z", prompt, "--usage-file", report);
    if (this.config.model) {
      args.push("-m", this.config.model);
    }

    const started = Date.now();
    const result = await this.runner.run("hermes", args, {
      cwd,
      timeoutMs: this.config.timeoutMs,
    });

    const usage = readUsage(report);
    fs.rmSync(report, { force: true });
    return this.answer(result, usage, started, context.skill);
  }

  /** A turn refused before it ran, which spends nothing and says why. */
  private refused(output: string): HarnessReply {
    return {
      text: "",
      run: { outcome: "failed", harness: this.name, model: this.config.model ?? "", durationMs: 0, costSource: "unknown", output },
    };
  }

  /** What the run was, with `unknown_skill` made visible in its own words. */
  private answer(
    result: CommandResult,
    usage: HermesUsage | undefined,
    started: number,
    skill: { readonly name: string } | undefined,
  ): HarnessReply {
    const tokens = tokensOf(usage);
    const model = usage?.model ?? this.config.model ?? "";
    const output = [result.stdout, result.stderr].filter(Boolean).join("\n").trim();
    // Hermes exits 1 with `unknown_skill` when `-s` names nothing it resolves;
    // the exit code alone cannot say that, and the report is absent, so this is
    // the one failure the run's own words have to name.
    const unknown = Boolean(skill && /unknown_skill/.test(output));
    const retry = retryAfterMs(usage);
    return {
      text: result.stdout,
      run: {
        outcome: unknown ? "failed" : classify(usage, result.ok),
        harness: this.name,
        model,
        tokens,
        ...cost(usage, tokens, model),
        durationMs: Date.now() - started,
        ...(retry === undefined ? {} : { retryAfterMs: retry }),
        output: unknown
          ? `${skill!.name}: hermes reported unknown_skill, so the profile cannot see the lent skill; run \`amy skills\` to see what it can lend\n${output}`
          : output,
      } satisfies AgentRun,
    };
  }

  /**
   * Why the profile would not load the lent skill, or undefined when it will.
   *
   * Hermes resolves `-s` by tier: the project, then the profile's own `skills`,
   * then `skills.external_dirs`. A profile created with `--clone` carries the
   * operator's skills into the middle tier, where a same-named copy wins over
   * amy's root; and a directory no tier names is never found at all. Both are
   * refused here, before `-z` starts.
   */
  private async refusal(skill: { readonly name: string; readonly path: string }, profileArgs: readonly string[]): Promise<string | undefined> {
    const file = path.join(path.resolve(skill.path), "SKILL.md");
    if (!fs.existsSync(file)) {
      return `/${skill.name} cannot be lent to hermes: ${file} does not exist, so the turn would run without the skill`;
    }
    if (!this.config.profile) return undefined;

    const local = path.join(this.hermesHome, "profiles", this.config.profile, "skills", skill.name, "SKILL.md");
    if (fs.existsSync(local)) {
      return `/${skill.name} would be loaded from the profile's own copy at ${local}, not the lent ${skill.path}; remove it or let amy lend that copy`;
    }

    const configured = await this.runner.run("hermes", [...profileArgs, "config", "get", "skills.external_dirs"]);
    const roots = configured.ok ? externalDirsIn(configured.stdout) : [];
    const lent = realpath(path.resolve(skill.path));
    const named = roots.some((root) => {
      const candidate = path.join(root, skill.name);
      return fs.existsSync(candidate) && realpath(candidate) === lent;
    });
    if (!named) {
      return `/${skill.name} cannot be lent to hermes: ${skill.path} is not in any root the profile reads (${roots.length ? roots.join(", ") : "skills.external_dirs names none"})`;
    }
    return undefined;
  }
}

/** The canonical path, so a link and its target are the same skill. */
function realpath(at: string): string {
  return fs.realpathSync(at);
}

export function readUsage(file: string): HermesUsage | undefined {
  if (!fs.existsSync(file)) return undefined;

  try {
    return JSON.parse(fs.readFileSync(file, "utf-8")) as HermesUsage;
  } catch {
    return undefined;
  }
}

/**
 * The token counts.
 *
 * `input_tokens` here **excludes** what was served from cache: the report's
 * own `total_tokens` is the sum of input, output and cache reads. That is the
 * opposite of the convention codex uses for a field of the same name, so
 * neither can borrow the other's mapping.
 */
export function tokensOf(usage: HermesUsage | undefined): TokenUsage | undefined {
  if (!usage) return undefined;

  return {
    input: usage.input_tokens ?? 0,
    output: usage.output_tokens ?? 0,
    cacheRead: usage.cache_read_tokens ?? 0,
    cacheWrite: usage.cache_write_tokens ?? 0,
  };
}

/**
 * What it cost, and how that is known.
 *
 * `cost_status: "included"` means a subscription covered the run, so zero is
 * the right answer rather than a missing one. Anything else Hermes puts in
 * `estimated_cost_usd` is, by its own word, an estimate from a price table,
 * so it is recorded as `computed` rather than `reported`: presenting somebody
 * else's estimate as a measurement is exactly what `costSource` exists to
 * stop.
 */
export function cost(
  usage: HermesUsage | undefined,
  tokens: TokenUsage | undefined,
  model: string,
): { costUsd?: number; costSource: AgentRun["costSource"] } {
  if (usage?.cost_status === "included") {
    return { costUsd: 0, costSource: "included" };
  }

  if (typeof usage?.estimated_cost_usd === "number" && usage.estimated_cost_usd > 0) {
    return { costUsd: usage.estimated_cost_usd, costSource: "computed" };
  }

  if (tokens) {
    const spec = specFor(model);
    if (spec) return { costUsd: costOf(spec, tokens), costSource: "computed" };
  }

  return { costSource: "unknown" };
}

/**
 * Which outcome this was.
 *
 * The report says plainly whether the run completed or failed, which beats
 * an exit code. Hermes publishes no quota status, so a rate limit reads as
 * `failed` rather than `rate-limited`.
 */
export function classify(usage: HermesUsage | undefined, exitOk: boolean): AgentOutcome {
  if (!usage) return exitOk ? "completed" : "abandoned";
  if (usage.failure_reason === "rate_limit") return "rate-limited";
  if (usage.failed === true) return "failed";
  if (usage.completed === true) return "completed";
  return exitOk ? "completed" : "failed";
}

/** Provider reset timestamps are optional; absent keeps the workflow fallback. */
export function retryAfterMs(usage: HermesUsage | undefined, now = Date.now()): number | undefined {
  if (usage?.failure_reason !== "rate_limit" || !usage.failure_resets_at) return undefined;
  const at = Date.parse(usage.failure_resets_at);
  return Number.isNaN(at) ? undefined : Math.max(0, at - now);
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  provider: {
    type: "string",
    description:
      "the Hermes provider whose account windows amy reads. Use openai-codex, anthropic, openrouter, or ollama-cloud; empty leaves the account usage unavailable rather than guessing",
    default: "",
  },
  model: {
    type: "string",
    description: "passed to the CLI as --model. Empty leaves the choice to hermes",
    default: "",
  },
  models: {
    type: "string[]",
    description:
      "the model tiers to offer the relay, cheapest first. One agent is contributed per tier, named `hermes:<model>`. Empty means a single agent named `hermes`",
    default: [],
  },
  profile: {
    type: "string",
    description:
      "the Hermes profile amy's runs use, so they read and write nothing of the operator's own Hermes. `amy setup hermes` creates it from the active profile when it is missing. A blank one is refused at boot",
    default: "amy",
  },
  timeoutMs: {
    type: "number",
    description: "how long one agent call may run before it is given up on",
    default: 30 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { HermesHarness, classify, cost, readUsage, retryAfterMs, tokensOf } from "./HermesHarness.js";
export type { HermesHarnessConfig, HermesUsage } from "./HermesHarness.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";
export { PROFILE_SETTINGS, checkProfile, prepareProfile } from "./profile.js";
export { HERMES_USAGE_PROVIDERS, HermesUsageReader, parseHermesUsage, parseOllamaCloudUsage } from "./usage.js";
export type { HermesUsageProvider, HermesUsageReaderOptions, OllamaCloudUsageClient } from "./usage.js";

import { NodeCommandRunner, definePlugin } from "@amykit/core";
import { contributeTiers, contributeUsage } from "@amykit/agent-kit";
import { HermesHarness } from "./HermesHarness.js";
import { configSchema } from "./config.js";
import { amySkillRoot, checkProfile, prepareProfile } from "./profile.js";
import { HermesUsageReader } from "./usage.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-hermes-agent",
  configSchema,
  setup: [
    {
      name: "hermes profile",
      run: ({ runner, settings, state }) => prepareProfile(runner, settings.profile, amySkillRoot(state)),
    },
  ],
  checks: [
    {
      name: "hermes profile",
      run: ({ settings, state }) => checkProfile(new NodeCommandRunner(), settings.profile, amySkillRoot(state)),
    },
  ],
  register(registry, ctx) {
    // A blank profile would run `-z` in the operator's own Hermes, which is
    // the one thing the setting exists to prevent.
    if (!ctx.config.profile.trim()) {
      throw new Error("`profile` is blank, which would run Hermes in the operator's own profile: name the profile amy's runs use, such as amy");
    }
    const tiers = ctx.config.models;

    contributeTiers(registry, {
      harness: "hermes",
      // Hermes writes its own account: `cost_status: "included"` for a run a
      // subscription or a local model covered, where zero is the right
      // answer rather than a missing one, and `estimated_cost_usd` for the
      // providers it prices itself. Neither needs a row here, and a local
      // model would never have one.
      pricesItsOwnRuns: true,
      models: tiers.length > 0 ? tiers : [(ctx.config.model) || ""],
      make: (model) =>
        new HermesHarness(ctx.runner, {
          model: model || undefined,
          timeoutMs: ctx.config.timeoutMs,
          profile: ctx.config.profile,
        }),
    });

    contributeUsage(
      registry,
      new HermesUsageReader(ctx.runner, {
        profile: ctx.config.profile,
        provider: ctx.config.provider,
        timeoutMs: ctx.config.timeoutMs,
      }),
    );
  },
});

import path from "node:path";
import { Check, CommandRunner } from "@amykit/core";

/**
 * What the profile amy runs in has switched off, and why each one.
 *
 * `-z` bypasses approvals, so in the operator's own Hermes a ticket run read
 * their memory and wrote what it learned back: memories, and skills patched
 * or created, with nobody asked. In amy's profile the run remembers nothing,
 * a skill it wants to write waits for a person, and the curator does not
 * rework skills between runs.
 */
export interface ProfileSetting {
  readonly key: string;
  readonly value: string;
  readonly says: string;
}

export const PROFILE_SETTINGS: readonly ProfileSetting[] = [
  { key: "memory.memory_enabled", value: "false", says: "remembers between runs" },
  { key: "memory.user_profile_enabled", value: "false", says: "keeps a profile of the user" },
  { key: "skills.write_approval", value: "true", says: "writes skills unasked" },
  { key: "curator.enabled", value: "false", says: "curates skills between runs" },
];

/** amy's own skill root, the one the relay installs into and lends from. */
export function amySkillRoot(state: string): string {
  return path.join(state, "skills");
}

/**
 * The profile setting that lets a run see amy's skills by name.
 *
 * `-s` resolves a skill through the roots Hermes scans, so the directory amy
 * owns has to be one of them. Written as a YAML list, which is how
 * `skills.external_dirs` is read, and checked by the doctor like the rest.
 */
export function externalDirsSetting(skillRoot: string): ProfileSetting {
  return { key: "skills.external_dirs", value: JSON.stringify([skillRoot]), says: "does not name amy's skills" };
}

/**
 * The directories `hermes config get skills.external_dirs` printed.
 *
 * The CLI prints a YAML list (`  - /a`) and accepts one, and a JSON array is
 * what amy writes; both read back as the same entries. Anything else is no
 * entries rather than a guess, because a prefix that merely starts the same is
 * a different directory.
 */
export function externalDirsIn(stdout: string): string[] {
  const text = stdout.trim();
  if (!text) return [];
  if (text.startsWith("[")) {
    try {
      const parsed = JSON.parse(text) as unknown;
      return Array.isArray(parsed) ? parsed.filter((one): one is string => typeof one === "string") : [];
    } catch {
      return [];
    }
  }
  return text
    .split("\n")
    .map((line) => /^\s*-\s*(.+?)\s*$/.exec(line)?.[1])
    .filter((one): one is string => Boolean(one))
    .map((one) => one.replace(/^["']|["']$/g, ""));
}

const DESCRIPTION = "amy's runs: one-shot ticket work that keeps no memory and writes no skill unasked";

/**
 * Makes the profile amy runs in, once, and keeps its skill root named.
 *
 * Cloned from the active profile, which carries the model, the provider keys
 * and the skills; Hermes reads the login through its credential pool, so the
 * clone needs no second sign-in. A profile that exists keeps whoever edited it
 * — the doctor reports drift — but `skills.external_dirs` is written either
 * way: `config set` replaces the list, so the directories it already named are
 * read first and kept beside amy's root.
 */
export async function prepareProfile(runner: CommandRunner, profile: string, skillRoot: string): Promise<Check> {
  const label = `hermes profile ${profile}`;
  const existed = await exists(runner, profile);
  if (!existed) {
    const created = await runner.run("hermes", ["profile", "create", profile, "--clone", "--no-alias", "--description", DESCRIPTION]);
    if (!created.ok) return { label, ok: false, detail: failure("could not create it", created) };

    for (const setting of PROFILE_SETTINGS) {
      const set = await runner.run("hermes", ["-p", profile, "config", "set", setting.key, setting.value]);
      if (!set.ok) return { label, ok: false, detail: failure(`created it, but could not set ${setting.key}`, set) };
    }
  }

  const current = await runner.run("hermes", ["-p", profile, "config", "get", "skills.external_dirs"]);
  const dirs = externalDirsIn(current.stdout);
  const named = dirs.includes(skillRoot) ? dirs : [...dirs, skillRoot];
  const set = await runner.run("hermes", ["-p", profile, "config", "set", "skills.external_dirs", JSON.stringify(named)]);
  if (!set.ok) {
    return {
      label,
      ok: false,
      detail: failure(`${existed ? "kept it" : "created it"}, but could not set skills.external_dirs`, set),
    };
  }

  return {
    label,
    ok: true,
    detail: existed
      ? "kept: it already exists, and amy's skill root is named beside the directories it had"
      : "created from the active profile, with memory, amy's skill root, unasked skill writes and the curator off",
  };
}

/**
 * Whether the profile exists and still has off what amy turned off.
 *
 * Red names the command that puts each one back, rather than putting it back:
 * somebody turned it on, and the doctor is not the place to overrule them.
 */
export async function checkProfile(runner: CommandRunner, profile: string, skillRoot: string): Promise<Check> {
  const label = `hermes profile ${profile}`;
  if (!(await exists(runner, profile))) {
    // Only the plugin's own setup: a bare clone copies the active profile's settings, so
    // it would come back remembering and curating, and the doctor still red.
    return { label, ok: false, detail: "missing: run `amy setup hermes`, which creates it with memory, amy's skill root, unasked skill writes and the curator off" };
  }

  const drifted: string[] = [];
  for (const setting of [...PROFILE_SETTINGS, externalDirsSetting(skillRoot)]) {
    const got = await runner.run("hermes", ["-p", profile, "config", "get", setting.key]);
    if (!holds(setting, got.stdout, skillRoot)) {
      const value = setting.key === "skills.external_dirs" ? `'${setting.value}'` : setting.value;
      drifted.push(`${setting.says} (\`hermes -p ${profile} config set ${setting.key} ${value}\`)`);
    }
  }

  return drifted.length === 0
    ? { label, ok: true }
    : { label, ok: false, detail: `the profile ${drifted.join("; ")}` };
}

/** Whether the profile still holds what amy set: a scalar verbatim, a list by its exact entry. */
function holds(setting: ProfileSetting, stdout: string, skillRoot: string): boolean {
  if (setting.key === "skills.external_dirs") return externalDirsIn(stdout).includes(skillRoot);
  return stdout.trim().toLowerCase() === setting.value;
}

async function exists(runner: CommandRunner, profile: string): Promise<boolean> {
  return (await runner.run("hermes", ["profile", "show", profile])).ok;
}

function failure(what: string, result: { stdout: string; stderr: string; exitCode: number | null }): string {
  const said = (result.stderr || result.stdout).trim();
  return said ? `${what}: ${said}` : `${what} (exit ${result.exitCode})`;
}

import { CommandRunner } from "@amykit/core";
import type { UsageReader, UsageResult } from "@amykit/agent-kit";

/** Providers whose account windows Hermes documents under `hermes usage`. */
export const HERMES_USAGE_PROVIDERS = ["openai-codex", "anthropic", "openrouter"] as const;
export type HermesUsageProvider = (typeof HERMES_USAGE_PROVIDERS)[number] | "ollama-cloud";

interface HermesUsageDocument {
  readonly windows?: unknown;
}

/**
 * A client that answers with Ollama Cloud's usage document, either the
 * balance response or the legacy fractions. Injected only by tests; a mounted
 * reader asks the balance endpoint with `OLLAMA_API_KEY` through the
 * command runner, the key on stdin rather than argv.
 */
export interface OllamaCloudUsageClient {
  readUsage(): Promise<unknown>;
}

export interface HermesUsageReaderOptions {
  readonly profile: string;
  readonly provider: HermesUsageProvider | string;
  readonly timeoutMs?: number;
  /** Test seam for a custom Cloud client; production uses Ollama's API key. */
  readonly ollamaCloud?: OllamaCloudUsageClient;
  readonly ollamaToken?: () => string | undefined;
}

/** Reads the account window for the Hermes provider the harness is configured for. */
export class HermesUsageReader implements UsageReader {
  readonly label: string;

  constructor(
    private readonly runner: CommandRunner,
    private readonly options: HermesUsageReaderOptions,
  ) {
    this.label = `Hermes (${options.provider})`;
  }

  async read(): Promise<UsageResult> {
    if (this.options.provider === "ollama-cloud") return await this.readOllamaCloud();

    if (!isHermesUsageProvider(this.options.provider)) {
      return unavailable(`Hermes does not provide usage windows for ${this.options.provider}`);
    }

    let result;
    try {
      result = await this.runner.run(
        "hermes",
        ["-p", this.options.profile, "usage", "--provider", this.options.provider, "--json"],
        { timeoutMs: this.options.timeoutMs },
      );
    } catch {
      return unavailable("Hermes usage is unavailable");
    }

    if (!result.ok) return unavailable("Hermes usage is unavailable");
    return parseHermesUsage(result.stdout);
  }

  /** Reads the documented balance endpoint with the operator's API key. */
  private async readOllamaCloud(): Promise<UsageResult> {
    if (this.options.ollamaCloud) {
      try {
        return parseOllamaCloudUsage(await this.options.ollamaCloud.readUsage());
      } catch {
        return unavailable("Ollama Cloud usage is unavailable");
      }
    }

    const token = this.options.ollamaToken?.() ?? process.env.OLLAMA_API_KEY;
    if (!token) return unavailable("Ollama Cloud usage is unavailable: no API key is configured");

    try {
      const result = await this.runner.run(
        "curl",
        ["--disable", "--fail", "--silent", "--show-error", "--config", "-", "https://ollama.com/api/balance"],
        {
          // Keep the bearer token off argv and process listings.
          stdin: `header = "Authorization: Bearer ${token}"\n`,
          timeoutMs: this.options.timeoutMs,
        },
      );
      return result.ok ? parseOllamaCloudUsage(result.stdout) : unavailable("Ollama Cloud usage is unavailable");
    } catch {
      return unavailable("Ollama Cloud usage is unavailable");
    }
  }
}

/** Maps Hermes's documented snake_case report to the host's usage contract. */
export function parseHermesUsage(json: string): UsageResult {
  let document: HermesUsageDocument | undefined;
  try {
    const parsed = JSON.parse(json) as unknown;
    if (typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)) document = parsed as HermesUsageDocument;
  } catch {
    return unavailable("Hermes usage returned invalid JSON");
  }

  if (!document) return unavailable("Hermes usage returned invalid JSON");
  if (!Array.isArray(document.windows)) return unavailable("Hermes usage returned no windows");
  const windows = document.windows.flatMap((value) => officialWindow(value));
  return windows.length > 0 ? { windows } : unavailable("Hermes usage returned no measured windows");
}

/**
 * Maps Ollama Cloud's legacy fractions and current balance response. Both are
 * provider-owned account measurements, so neither borrows Amy's ledger.
 */
export function parseOllamaCloudUsage(value: unknown): UsageResult {
  const document = typeof value === "string" ? parseDocument(value) : value;
  const included = objectAt(document, "included");
  const balance = included ? balanceWindows(included) : [];
  if (balance.length > 0) return { windows: balance };
  // No balance and allowance to measure against: whatever is left is the legacy fractions, wherever they sit.
  const windows = included ? legacyWindows({ limits: included }) : legacyWindows(document);
  return windows.length > 0 ? { windows, unofficial: true } : unavailable("Ollama Cloud usage returned no measured windows");
}

function parseDocument(value: string): unknown {
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return undefined;
  }
}

/** Current API: one included-credit allowance with the provider's real period. */
function balanceWindows(included: Record<string, unknown>): { label: string; usedPercent: number; startsAt?: string; resetsAt?: string }[] {
  const balance = number(included.balance_usd);
  const allowance = number(included.allowance_usd);
  if (balance === undefined || allowance === undefined || allowance <= 0) return [];
  const period = objectAt(included, "period");
  const startsAt = iso(period?.from);
  const resetsAt = iso(period?.until);
  return [{
    label: "Included credits",
    usedPercent: percentOf(balance, allowance),
    ...(startsAt ? { startsAt } : {}),
    ...(resetsAt ? { resetsAt } : {}),
  }];
}

/** Legacy API responses use 0..1 fractions under session and weekly limits. */
function legacyWindows(value: unknown): { label: string; usedPercent: number }[] {
  const limits = objectAt(value, "limits");
  if (!limits) return [];
  return [
    unofficialWindow("Session", limits.session),
    unofficialWindow("Weekly", limits.weekly),
    unofficialWindow("Monthly", limits.monthly),
  ].flatMap((window) => (window ? [window] : []));
}

function officialWindow(value: unknown): { label: string; usedPercent: number; startsAt?: string; resetsAt?: string }[] {
  if (!isObject(value) || typeof value.label !== "string") return [];
  const usedPercent = value.used_percent;
  if (!percent(usedPercent)) return [];
  const startsAt = iso(value.starts_at);
  const resetsAt = iso(value.resets_at);
  return [{ label: value.label, usedPercent, ...(startsAt ? { startsAt } : {}), ...(resetsAt ? { resetsAt } : {}) }];
}

function unofficialWindow(label: string, value: unknown): { label: string; usedPercent: number } | undefined {
  const window = object(value);
  const fraction = window?.usage;
  if (typeof fraction !== "number" || !Number.isFinite(fraction)) return undefined;
  return { label, usedPercent: clamp(fraction * 100, 0, 100) };
}

function unavailable(reason: string): UsageResult {
  return { unavailable: reason };
}

function isHermesUsageProvider(provider: string): provider is (typeof HERMES_USAGE_PROVIDERS)[number] {
  return (HERMES_USAGE_PROVIDERS as readonly string[]).includes(provider);
}

function objectAt(value: unknown, key: string): Record<string, unknown> | undefined {
  const root = object(value);
  return object(root?.[key]);
}

function object(value: unknown): Record<string, unknown> | undefined {
  return isObject(value) ? value : undefined;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function percent(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 100;
}

function iso(value: unknown): string | undefined {
  return typeof value === "string" && !Number.isNaN(Date.parse(value)) ? value : undefined;
}

function number(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function percentOf(balance: number, allowance: number): number {
  return Math.round(clamp((1 - balance / allowance) * 100, 0, 100) * 1_000_000) / 1_000_000;
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}
